function capitalizeAndRemoveDuplicates(obj, seen = new WeakMap()) {
  if (typeof obj !== 'object' || obj === null) {
    return obj;
  }

  if (seen.has(obj)) {
    return seen.get(obj);
  }

  let result;

  if (Array.isArray(obj)) {
    result = [];
    seen.set(obj, result);

    for (let i = 0; i < obj.length; i++) {
      const capitalized = capitalizeAndRemoveDuplicates(obj[i], seen);
      if (!result.some(item => isEqual(item, capitalized))) {
        result.push(capitalized);
      }
    }
  } else {
    result = {};
    seen.set(obj, result);

    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        const capitalized = capitalizeAndRemoveDuplicates(obj[key], seen);
        if (!Object.values(result).some(value => isEqual(value, capitalized))) {
          result[key] = capitalized;
        }
      }
    }
  }

  return result;
}

function isEqual(a, b) {
  if (typeof a !== typeof b) {
    return false;
  }

  if (typeof a !== 'object' || a === null) {
    return a === b;
  }

  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);

  if (aKeys.length !== bKeys.length) {
    return false;
  }

  for (const key of aKeys) {
    if (!isEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}

