public class SecondSmallestEvenElement {
    public static void main(String[] args) {
        int[] arr = {102, 108, 120, 114, 126, 132, 138, 150, 156, 162};
        int secondSmallestEven = findSecondSmallestEven(arr);
        System.out.println("Second Smallest Even Element: " + secondSmallestEven);
