    public static int findSecondSmallestEven(int[] arr) {
        if (arr.length < 10 || arr.length > 200) {
            throw new IllegalArgumentException("Array size should be at least 10 and cannot exceed 200.");
        }

        for (int num : arr) {
            if (num < 100 || num > 1000 || num % 3 != 0) {
                throw new IllegalArgumentException("Array elements should be unique, positive, divisible by 3, and within the range of 100 to 1000.");
            }
        }

        int smallestEven = Integer.MAX_VALUE;
        int secondSmallestEven = Integer.MAX_VALUE;

        for (int num : arr) {
            if (num < smallestEven && num % 2 == 0) {
                secondSmallestEven = smallestEven;
                smallestEven = num;
            } else if (num < secondSmallestEven && num % 2 == 0 && num != smallestEven) {
                secondSmallestEven = num;
            }
        }

        if (secondSmallestEven == Integer.MAX_VALUE) {
            throw new IllegalArgumentException("No second smallest even element found.");
        }

        return secondSmallestEven;
    }
}
