public class ReverseArray {
    public static void main(String[] args) {
        int[] arr = {1, -2, 3, -4, 5};
        int[] reversedArr = reverseUniqueArray(arr);
        printArray(reversedArr);
    }

    public static int[] reverseUniqueArray(int[] arr) {
        if (arr == null || arr.length == 0) {
            System.out.println("Error: Input array is null or empty");
            return new int[0];
        }

        int[] uniqueArr = removeDuplicates(arr);
        reverseArray(uniqueArr);
        return uniqueArr;
    }

    public static int[] removeDuplicates(int[] arr) {
        boolean[] isVisited = new boolean[arr.length];
        int uniqueCount = 0;

        for (int i = 0; i < arr.length; i++) {
            if (!isVisited[i]) {
                isVisited[i] = true;
                uniqueCount++;

                for (int j = i + 1; j < arr.length; j++) {
                    if (arr[j] == arr[i]) {
                        isVisited[j] = true;
                    }
                }
            }
        }

        int[] uniqueArr = new int[uniqueCount];
        int index = 0;

        for (int i = 0; i < arr.length; i++) {
            if (isVisited[i]) {
                uniqueArr[index++] = arr[i];
            }
        }

        return uniqueArr;
    }

    public static void reverseArray(int[] arr) {
        int start = 0;
        int end = arr.length - 1;

        while (start < end) {
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }
    }

    public static void printArray(int[] arr) {
        System.out.print("[");
        for (int i = 0; i < arr.length; i++) {
            if (i != arr.length - 1) {
                System.out.print(arr[i] + ", ");
            } else {
                System.out.print(arr[i]);
            }
        }
        System.out.println("]");
    }
}
