def extract_values(input_string: str, keys: List[str]) -> Dict[str, Optional[str]]:
    values = {}
    tokens = input_string.split()
    i = 0
    while i < len(tokens):
        key = tokens[i]
        if key in keys:
            value = tokens[i + 1][1:-1]  # Extract the value within square brackets
            values[key] = value
        i += 2
    for key in keys:
        if key not in values:
            values[key] = None
    return values
