function countUniqueCSSClasses(cssContent) {
    // Regular expression to match CSS classes
    const classRegex = /\.([a-zA-Z][\w-]*)/g;
    let uniqueClasses = new Set();

    // Extract and store unique CSS classes
    let match;
    while ((match = classRegex.exec(cssContent)) !== null) {
        uniqueClasses.add(match[1]);
    }

    return uniqueClasses.size;
}

