public PsiElement findTargetElement(StructureViewTreeElement root, PsiElement target) {
    if (root == null || target == null) {
        return null;
    }

    if (root.contains(target)) {
        return target;
    }

    if (root.getChildren() != null) {
        for (StructureViewTreeElement child : root.getChildren()) {
            PsiElement foundElement = findTargetElement(child, target);
            if (foundElement != null) {
