        for (MediaFile mediaFile : mediaFiles) {
            if (mediaFile.title.contains(searchCriteria) || mediaFile.type.contains(searchCriteria) || mediaFile.genre.contains(searchCriteria)) {
                searchResults.add(mediaFile);
            }
        }
        return searchResults;
    }
