Here is a script in JavaScript that reverses a string while maintaining the position of each punctuation mark, special character, and whitespace:

```javascript
function reverseString(text) {
  let reversedText = "";
  let i = text.length - 1;

  while (i >= 0) {
    if (isPunctuation(text[i]) || isSpecialCharacter(text[i]) || isWhitespace(text[i])) {
      reversedText += text[i];
    } else {
      let j = i;
      while (j >= 0 && !isPunctuation(text[j]) && !isSpecialCharacter(text[j]) && !isWhitespace(text[j])) {
        j--;
      }
      let word = text.substring(j + 1, i + 1);
      reversedText += reverseWord(word);
      i = j;
    }
    i--;
  }

  return reversedText;
}

function isPunctuation(character) {
  return /[!"#$%&'()*+,-./:;<=>?@[\]^_`{|}~]/.test(character);
}

function isSpecialCharacter(character) {
  return /[\s\t\n\r\v]/.test(character);
}

function isWhitespace(character) {
  return /\s/.test(character);
}

function reverseWord(word) {
  let reversedWord = "";
  let i = word.length - 1;

  while (i >= 0) {
    reversedWord += word[i];
    i--;
  }

  return reversedWord;
}

let text = "hello, world! How are you?";
let reversedText = reverseString(text);
console.log(reversedText);
