def transform_string_to_dict(input_string):
    colors = input_string.split(", ")
    color_dict = {}

    for color in colors:
        if ":" not in color:
            raise ValueError("Invalid format. Each color entry should be separated by a colon.")

        color_parts = color.split(":")
        if len(color_parts) != 2:
            raise ValueError("Invalid format. Each color entry should consist of a color name followed by a space and a hex code, separated by a colon.")

        color_name = color_parts[0].lower().strip()
        if not color_name.isalpha():
            raise ValueError("Invalid format. The color name should only contain alphabetical characters.")

        hex_code = color_parts[1].strip()
        if not (hex_code.startswith("#") and len(hex_code) == 7 and all(c in "0123456789ABCDEF" for c in hex_code[1:])):
            raise ValueError("Invalid format. The hex code should start with '#' and be followed by exactly six hexadecimal characters.")

        color_dict[color_name] = hex_code

    return color_dict

