```rust
fn infix_to_postfix(expression: &str) -> Result<String, String> {
    let mut output = String::new();
    let mut stack = Vec::new();
    let precedence = |c: char| -> i32 {
        match c {
            '+' | '-' => 1,
            '*' | '/' => 2,
            _ => 0,
        }
    };

    for token in expression.chars() {
        match token {
            '0'..='9' | '.' => output.push(token),
            '(' => stack.push(token),
            ')' => {
                while let Some(op) = stack.pop() {
                    if op == '(' {
                        break;
                    }
                    output.push(op);
                }
            }
            '+' | '-' | '*' | '/' => {
                while let Some(op) = stack.last() {
                    if *op != '(' && precedence(*op) >= precedence(token) {
                        output.push(stack.pop().unwrap());
                    } else {
                        break;
                    }
                }
                stack.push(token);
                output.push(' ');
            }
            _ => return Err(format!("Invalid character: {}", token)),
        }
    }

    while let Some(op) = stack.pop() {
        if op == '(' {
            return Err("Mismatched parentheses".to_string());
        }
        output.push(op);
    }

    Ok(output)
}

fn evaluate_postfix(expression: &str) -> Result<f64, String> {
    let mut stack = Vec::new();

    for token in expression.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop().ok_or("Invalid expression".to_string())?.parse::<f64>()?;
                let a = stack.pop().ok_or("Invalid expression".to_string())?.parse::<f64>()?;
                match token {
                    "+" => stack.push(a + b),
                    "-" => stack.push(a - b),
                    "*" => stack.push(a * b),
                    "/" => stack.push(a / b),
                    _ => return Err("Invalid operator".to_string()),
                }
            }
            _ => stack.push(token.parse::<f64>().map_err(|_| "Invalid number".to_string())?),
        }
    }

    stack.pop().ok_or("Invalid expression".to_string())
}
```

