To create a matrix NxN with values of 0 filled in, where N is a prime number, and to fill in the diagonal of the matrix with a value of 1, and the remaining cells with prime numbers in ascending order, starting from 2, you can use the following function in Python:

```python
import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    for i in range(5, int(math.sqrt(n)) + 1, 6):
        if n % i == 0 or n % (i + 2) == 0:
            return False
    return True

def create_prime_matrix(n):
    if not is_prime(n):
        raise ValueError("N must be a prime number.")

    matrix = [[0 for _ in range(n)] for _ in range(n)]

    for i in range(n):
        matrix[i][i] = 1

    prime = 2
    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 0:
                while not is_prime(prime):
                    prime += 1
                matrix[i][j] = prime
                prime += 1

    return matrix
```

Here's an example usage of the function:

```python
matrix = create_prime_matrix(5)
for row in matrix:
    print(row)
```

