using System;
using System.Threading.Tasks;

public interface IAsyncRunnable
{
    Task Run();
}

public class AsyncTaskRunner
{
    public async Task<string[]> RunTasksAsync(IAsyncRunnable[] tasks)
    {
        var results = new string[tasks.Length];
        var taskResults = new Task<string>[tasks.Length];

        for (int i = 0; i < tasks.Length; i++)
        {
            taskResults[i] = ExecuteTaskAsync(tasks[i], i);
        }

        for (int i = 0; i < tasks.Length; i++)
        {
            results[i] = await taskResults[i];
        }

        return results;
    }

    private async Task<string> ExecuteTaskAsync(IAsyncRunnable task, int index)
    {
        await task.Run();
        return $"Result of task {index + 1}";
    }
}
