class PDFReportGenerator:
    def __init__(self):
        self.file_path = None
        self.file_format = None
        self.data = None
        self.selected_columns = []

    def prompt_file_path(self):
        while True:
            self.file_path = input("Enter the file path of the dataset: ")
            if os.path.exists(self.file_path):
                self.file_format = os.path.splitext(self.file_path)[1][1:]
                if self.file_format in ['csv', 'json', 'xlsx']:
                    break
                else:
                    print("Invalid file format. Please choose a CSV, JSON, or Excel file.")
            else:
                print("File not found. Please enter a valid file path.")

    def load_data(self):
        if self.file_format == 'csv':
            self.data = pd.read_csv(self.file_path)
        elif self.file_format == 'json':
            self.data = pd.read_json(self.file_path)
        elif self.file_format == 'xlsx':
            self.data = pd.read_excel(self.file_path)

    def display_column_options(self):
        print("Available columns:")
        for i, column in enumerate(self.data.columns):
            print(f"{i+1}. {column}")
        print("Enter the numbers corresponding to the columns you want to include in the PDF report (comma-separated):")

    def select_columns(self):
        self.display_column_options()
        while True:
            selected_columns = input("Selected columns: ")
            try:
                selected_columns = [int(col_num) for col_num in selected_columns.split(",")]
                if all(col_num > 0 and col_num <= len(self.data.columns) for col_num in selected_columns):
                    self.selected_columns = [self.data.columns[col_num - 1] for col_num in selected_columns]
                    break
                else:
                    print("Invalid column numbers. Please choose valid column numbers.")
            except ValueError:
                print("Invalid input format. Please enter comma-separated column numbers.")

    def generate_pdf_report(self):
        pdf = FPDF()
        pdf.set_font("Arial", size=12)
        pdf.add_page()
        pdf.cell(0, 10, "PDF Report", ln=True, align='C')
        pdf.cell(0, 10, "", ln=True)

        table_data = self.data[self.selected_columns].values.tolist()
        table_headers = self.selected_columns
        pdf.cell(0, 10, tabulate(table_data, headers=table_headers, tablefmt='grid'), ln=True)

        file_path = input("Enter the file path and name for the PDF report: ")
        if os.path.exists(file_path):
            print("File already exists. Please choose a different file path and name.")
            return

        pdf.output(file_path)
        print("PDF report created and saved successfully.")

    def generate_report(self):
        self.prompt_file_path()
        self.load_data()
        self.select_columns()
        self.generate_pdf_report()

report_generator = PDFReportGenerator()
report_generator.generate_report()
