function getBusinessDaysLeft(date) {
  // Convert the given date string into a Date object
  const targetDate = new Date(date);

  // Get the current date
  const currentDate = new Date();

  // Counter variable to keep track of business days
  let businessDays = 0;

  // Loop from current date to the target date
  while (currentDate <= targetDate) {
    // Check if the current day is a weekday (Monday to Friday)
    if (currentDate.getDay() >= 1 && currentDate.getDay() <= 5) {
      // Check if the current day is not a holiday
      if (!isHoliday(currentDate)) {
        businessDays++;
      }
    }

    // Move to the next day
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return businessDays;
}

