class Point3D {
  constructor(x, y, z) {
    this.x = x;
    this.y = y;
    this.z = z;
  }

  distanceFromOrigin() {
    const distance = Math.sqrt(Math.pow(this.x, 2) + Math.pow(this.y, 2) + Math.pow(this.z, 2));
    return distance;
  }

  translate(dx, dy, dz) {
    this.x += dx;
    this.y += dy;
    this.z += dz;
  }

  isOrigin() {
    return this.x === 0 && this.y === 0 && this.z === 0;
  }

