    const midpointX = (point1.x + point2.x) / 2;
    const midpointY = (point1.y + point2.y) / 2;
    const midpointZ = (point1.z + point2.z) / 2;
    return new Point3D(midpointX, midpointY, midpointZ);
  }

  rotateX(angle) {
    const radians = angle * (Math.PI / 180);
    const newY = this.y * Math.cos(radians) - this.z * Math.sin(radians);
    const newZ = this.y * Math.sin(radians) + this.z * Math.cos(radians);
    this.y = newY;
    this.z = newZ;
  }

  rotateY(angle) {
