    const newX = this.x * Math.cos(radians) - this.y * Math.sin(radians);
    const newY = this.x * Math.sin(radians) + this.y * Math.cos(radians);
    this.x = newX;
    this.y = newY;
  }

  toString() {
    return "(" + this.x + "," + this.y + "," + this.z + ")";
  }
