```javascript
const fruits = ['apple', 'banana', 'mango', 'cherry'];
const weights = [1, 2, 3, 4];

function getRandomIndex(arr) {
  return Math.floor(Math.random() * arr.length);
}

function getRandomUniqueItems(arr, weights) {
  const selectedItems = [];
  const selectedWeights = [];
  const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);

  while (selectedItems.length < arr.length) {
    const randomIndex = getRandomIndex(arr);
    const item = arr[randomIndex];
    const weight = weights[randomIndex];

    if (weight !== 0 && !selectedItems.includes(item)) {
      const probability = weight / totalWeight;

      if (Math.random() < probability) {
        selectedItems.push(item);
        selectedWeights.push(weight);
      }
    }
  }

  const sortedItems = selectedItems.sort((a, b) => {
    const indexA = fruits.indexOf(a);
    const indexB = fruits.indexOf(b);

    return selectedWeights[indexB] - selectedWeights[indexA];
  });

  return sortedItems;
}

const selectedItems = getRandomUniqueItems(fruits, weights);
console.log(selectedItems);
