        } else if (arr1[i] > arr2[j]) {
            if (merged.empty() || merged.back() != arr2[j])
                merged.push_back(arr2[j]);
            j++;
        } else {
            if (merged.empty() || merged.back() != arr1[i])
                merged.push_back(arr1[i]);
            i++;
            j++;
        }
    }

    while (i < arr1.size()) {
        if (merged.empty() || merged.back() != arr1[i])
            merged.push_back(arr1[i]);
        i++;
    }

    while (j < arr2.size()) {
        if (merged.empty() || merged.back() != arr2[j])
            merged.push_back(arr2[j]);
        j++;
    }

    return merged;
}

int main() {
    std::vector<int> arr1 = {1, 3, 5, 7, 9};
    std::vector<int> arr2 = {2, 4, 6, 8};

    std::vector<int> merged = mergeArrays(arr1, arr2);

    std::cout << "Merged array: ";
    for (int num : merged) {
        std::cout << num << " ";
    }

    return 0;
}
```

This program takes two sorted arrays (`arr1` and `arr2`) as input and merges them into a new sorted array `merged`. It iterates over the two arrays using two pointers (`i` and `j`) and compares the elements at the corresponding positions. If an element is smaller than the other, it is added to the merged array, and the corresponding pointer is incremented. If the two elements are equal, only one of them is added to the merged array. Finally, any remaining elements in either array are added to the merged array.

The time complexity of this program is O(n), where n is the total number of elements in the merged array, because we iterate over both arrays once. The space complexity is also O(n), as we use an additional vector to store the merged array.

