def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_sum_of_primes(nums, index):
    if index == len(nums):
        return 0
    current_num = nums[index]
    if is_prime(current_num):
        return current_num + find_sum_of_primes(nums, index + 1)
    else:
        return find_sum_of_primes(nums, index + 1)

# Example usage
