#include <stdio.h>

void merge(int arr[], int left[], int left_size, int right[], int right_size) {
    int i = 0, j = 0, k = 0;

    while (i < left_size && j < right_size) {
        if (left[i] < right[j]) {
            arr[k++] = left[i++];
        } else if (left[i] > right[j]) {
            arr[k++] = right[j++];
        } else {
            i++;
            j++;
        }
    }

    while (i < left_size) {
        arr[k++] = left[i++];
    }

    while (j < right_size) {
        arr[k++] = right[j++];
    }
}

void mergeSort(int arr[], int n) {
    if (n <= 1) {
        return;
    }

    int mid = n / 2;
    int left[mid];
    int right[n - mid];

    for (int i = 0; i < mid; i++) {
        left[i] = arr[i];
    }

    for (int i = mid; i < n; i++) {
        right[i - mid] = arr[i];
    }

    mergeSort(left, mid);
    mergeSort(right, n - mid);

    merge(arr, left, mid, right, n - mid);
}

void printDistinctElements(int arr[], int n) {
    // Sort the array using merge sort
    mergeSort(arr, n);

    // Print distinct elements
    for (int i = 0; i < n; i++) {
        if (i == 0 || arr[i] != arr[i - 1]) {
            printf("%d ", arr[i]);
        }
    }

    printf("\n");
}

int main() {
    int arr[] = {7, 2, 5, 2, 8, 7, 10, 9, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    printDistinctElements(arr, n);

    return 0;
}
