  counter: 0
};

const counterReducer = (state = initialState, action) => {
  switch (action.type) {
    case "INCREMENT":
      if (typeof action.payload !== "number" || isNaN(action.payload) || !isFinite(action.payload)) {
        return state;
      }
      return {
        ...state,
        counter: state.counter + action.payload
      };
    case "DECREMENT":
      if (typeof action.payload !== "number" || isNaN(action.payload) || !isFinite(action.payload)) {
        return state;
      }
      return {
        ...state,
        counter: state.counter - action.payload
      };
    default:
      return state;
  }
};

export default counterReducer;

