      onButtonClick();
      setBackgroundColor(hoverColor);
      setCounter(counter + 1);
    }
  };

  const handleHover = () => {
    if (!disabled && !loading) {
      setIsHovered(true);
      setBackgroundColor(hoverColor);
    }
  };

