const express = require('express');
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const app = express();
const port = 3000;
const logDirectory = path.join(__dirname, 'logs');

// Create log directory if it doesn't exist
if (!fs.existsSync(logDirectory)) {
  fs.mkdirSync(logDirectory);
}

// Create a rotating log file
const accessLogStream = fs.createWriteStream(path.join(logDirectory, 'access.log'), { flags: 'a' });

// Middleware to log timestamp and IP address
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const ip = req.ip || req.connection.remoteAddress;
  const logMessage = `${timestamp} - ${ip} - ${req.method} - ${req.originalUrl}\n`;

  accessLogStream.write(logMessage);
  next();
});

// GET request handler
app.get('/', (req, res) => {
  res.send('Hello, World!');
});

// Error handling middleware
app.use((req, res, next) => {
  const error = new Error('Not Found');
  error.status = 404;
  next(error);
});

// Global error handler
app.use((error, req, res, next) => {
  const timestamp = new Date().toISOString();
  const ip = req.ip || req.connection.remoteAddress;
  const logMessage = `${timestamp} - ${ip} - ${error.message}\n`;

  accessLogStream.write(logMessage);
  res.status(error.status || 500).send(error.message);
});

// Start the server
app.listen(port, () => {
  console.log(`Server is running on http://localhost:${port}`);
});
```

In this example, we use the `express` module to create a web server. The server listens on port 3000 and responds with "Hello, World!" to any incoming GET request. The `app.use` middleware is used to log the timestamp and IP address of each incoming request to a log file. The log file is rotated every day and stored in the `logs` directory.

The error handling middleware handles any 404 errors by creating a new `Error` object with the message "Not Found" and setting the status to 404. The global error handler logs the error message, timestamp, and IP address of the request. If the error has a status, it is returned as the HTTP status code; otherwise, a 500 status code is used.

