import java.util.HashMap;
import java.util.Map;

public class StringAnalyzer {
    private String inputString;

    public StringAnalyzer(String inputString) {
        this.inputString = inputString;
    }

    public int getUppercaseCount() {
        int count = 0;
        for (char c : inputString.toCharArray()) {
            if (Character.isUpperCase(c)) {
                count++;
            }
        }
        return count;
    }

    public int getLowercaseCount() {
        int count = 0;
        for (char c : inputString.toCharArray()) {
            if (Character.isLowerCase(c)) {
                count++;
            }
        }
        return count;
    }

    public int getNumberCount() {
        int count = 0;
        for (char c : inputString.toCharArray()) {
            if (Character.isDigit(c)) {
                count++;
            }
        }
        return count;
    }

    public int getSpecialCharCount() {
        int count = 0;
        for (char c : inputString.toCharArray()) {
            if (!Character.isLetterOrDigit(c) && !Character.isWhitespace(c)) {
                count++;
            }
        }
        return count;
    }

    public int getWhitespaceCount() {
        int count = 0;
        for (char c : inputString.toCharArray()) {
            if (Character.isWhitespace(c)) {
                count++;
            }
        }
        return count;
    }

    public double getUppercasePercentage() {
        return (double) getUppercaseCount() / inputString.length() * 100;
    }

    public double getLowercasePercentage() {
        return (double) getLowercaseCount() / inputString.length() * 100;
    }

    public double getNumberPercentage() {
        return (double) getNumberCount() / inputString.length() * 100;
    }

    public double getSpecialCharPercentage() {
        return (double) getSpecialCharCount() / inputString.length() * 100;
    }

    public double getWhitespacePercentage() {
        return (double) getWhitespaceCount() / inputString.length() * 100;
    }

    public String removeDuplicates() {
        StringBuilder result = new StringBuilder();
        Map<Character, Boolean> seenCharacters = new HashMap<>();
        for (char c : inputString.toCharArray()) {
            if (!seenCharacters.containsKey(c)) {
                result.append(c);
                seenCharacters.put(c, true);
            }
        }
        return result.toString();
    }

    public String reverseWords() {
        StringBuilder result = new StringBuilder();
        String[] words = inputString.split("\\s+");
        for (int i = words.length - 1; i >= 0; i--) {
            result.append(words[i]).append(" ");
        }
        return result.toString().trim();
    }

    public String toCamelCase() {
        StringBuilder result = new StringBuilder();
        String[] words = inputString.split("[\\s-_]+");
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (i == 0) {
                result.append(Character.toLowerCase(word.charAt(0)));
            } else {
                result.append(Character.toUpperCase(word.charAt(0)));
            }
            if (word.length() > 1) {
                result.append(word.substring(1).toLowerCase());
            }
        }
        return result.toString();
    }
}
```

This implementation stores the input string as an instance variable and provides various methods to calculate the frequency of different types of characters and determine their percentage. The `removeDuplicates` method uses a `HashMap` to keep track of seen characters and only appends unseen characters to the result. The `reverseWords` method splits the input string into words using whitespace as the delimiter, reverses the order of the words, and then joins them back with a space separator. The `toCamelCase` method splits the input string into words using various word separators as delimiters, converts the first letter of each word to uppercase except for the first word, and joins them back without any separators.

To handle the requirements:

1. The class only stores the input string and uses additional memory only for the `removeDuplicates` method.
2. The frequency calculation methods have a time complexity of O(n), where n is the length of the input string.
3. The `removeDuplicates` method uses a `HashMap` to handle Unicode characters properly.
4. The `reverseWords` method properly handles punctuation marks and special characters by using whitespace as the delimiter and joining the reversed words with a space separator.
5. The `toCamelCase` method handles different word separators such as hyphens, underscores, and spaces by using a regular expression to split the input string.

