function sortObjects(arr) {
  // Create a new array to store the sorted objects
  const sortedArr = [...arr];

  // Check if all objects have the required properties
  for (let i = 0; i < sortedArr.length; i++) {
    if (!sortedArr[i].hasOwnProperty('name') || !sortedArr[i].hasOwnProperty('age') || !sortedArr[i].hasOwnProperty('id')) {
      throw new Error('All objects must have name, age, and id properties');
    }
  }

  // Implement the sorting algorithm
  sortedArr.sort((a, b) => {
    // Sort by age in ascending order
    if (a.age < b.age) {
      return -1;
    } else if (a.age > b.age) {
      return 1;
    }

    // If age is the same, sort by name in descending order
    if (a.name < b.name) {
      return 1;
    } else if (a.name > b.name) {
      return -1;
    }

    // If age and name are the same, sort by id in ascending order
    if (a.id < b.id) {
      return -1;
    } else if (a.id > b.id) {
      return 1;
    }

    return 0;
  });

  return sortedArr;
}
