Here's a Java code that converts the given string to an array, excluding vowels and special characters, removing duplicate elements, and sorting the array in ascending order:

```java
import java.util.Arrays;
import java.util.HashSet;

public class StringToArray {
    public static void main(String[] args) {
        String str = "Hello @#& World";
        String[] result = convertStringToArray(str);

        // Print the resulting array
        for (String s : result) {
            System.out.println(s);
        }
    }

    public static String[] convertStringToArray(String str) {
        // Remove vowels and special characters from the string
        String filteredStr = str.replaceAll("[aeiouAEIOU@#&]", "");

        // Split the filtered string into an array of words
        String[] words = filteredStr.split("\\s+");

        // Remove duplicate elements using HashSet
        HashSet<String> uniqueWords = new HashSet<>(Arrays.asList(words));

        // Convert the unique words back to an array
        String[] result = uniqueWords.toArray(new String[0]);

        // Sort the array in ascending order
        Arrays.sort(result);

        return result;
    }
}
