function toTitleCase(str) {
  // Remove leading and trailing spaces
  str = str.trim();

  // Convert string to lowercase
  str = str.toLowerCase();

  // Split the string into words
  let words = str.split(" ");

  // Loop through each word
  for (let i = 0; i < words.length; i++) {
    let word = words[i];

    // Capitalize the first letter of the word
    word = word.charAt(0).toUpperCase() + word.slice(1);

    // Check if the word is in the list of excluded words
    if (word !== "The" && word !== "And" && word !== "Or" && word !== "But") {
      // Split the word by hyphens
      let hyphenatedWords = word.split("-");

      // Loop through each hyphenated word
      for (let j = 0; j < hyphenatedWords.length; j++) {
        let hyphenatedWord = hyphenatedWords[j];

        // Capitalize the first letter of the hyphenated word
        hyphenatedWord = hyphenatedWord.charAt(0).toUpperCase() + hyphenatedWord.slice(1);

        // Replace the hyphenated word in the array
        hyphenatedWords[j] = hyphenatedWord;
      }

      // Join the hyphenated words with hyphens
      word = hyphenatedWords.join("-");
    }

    // Replace the word in the array
    words[i] = word;
  }

  // Join the words with spaces
  str = words.join(" ");

  return str;
}

