import cirq

def are_measurements_terminal(circuit):
    last_measurement = {}  # Dictionary to store the last measurement for each qubit
    for moment in circuit:
        for op in moment:
            if isinstance(op, cirq.GateOperation) and isinstance(op.gate, cirq.MeasurementGate):
                qubit = op.qubits[0]
                last_measurement[qubit] = op
    for moment in circuit:
        for op in moment:
            if isinstance(op, cirq.GateOperation) and op not in last_measurement.values():
                return False  # If any non-terminal operation is found after the last measurement, return False
    return True  # If all measurements are terminal, return True
