use std::io::{BufRead, BufReader};
use std::io::Cursor;

fn process_output(output: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut reading = false;

    let reader = BufReader::new(Cursor::new(output));
    for line in reader.lines() {
        if let Ok(line) = line {
            if line.contains("END") {
                break;
            }
            if reading {
                if let Some(first_quote) = line.find('"') {
                    let end_quote = line[first_quote + 1..].find('"').map(|i| first_quote + i + 1).unwrap_or(0);
                    let extracted_data = line[first_quote + 1..end_quote].to_string();
                    result.push(extracted_data);
                }
            } else if line.contains('"') {
                reading = true;
            }
        }
    }
    result
}

fn main() {
    let output = "Some initial output\nMore lines\n\"Data 1\"\n\"Data 2\"\nEND\nAdditional output";
    let extracted_data = process_output(output);
    for data in extracted_data {
        println!("{}", data);
    }
}
