#include <iostream>
#include <string>
#include <cmath>

bool isBinary(const std::string& number) {
    for (char c : number) {
        if (c != '0' && c != '1') {
            return false;
        }
    }
    return true;
}

bool isHexadecimal(const std::string& number) {
    for (char c : number) {
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
            return false;
        }
    }
    return true;
}

int binaryToDecimal(const std::string& binary) {
    int decimal = 0;
    int power = 0;

    for (int i = binary.length() - 1; i >= 0; --i) {
        if (binary[i] == '1') {
            decimal += pow(2, power);
        }
        ++power;
    }

    return decimal;
}

int hexadecimalToDecimal(const std::string& hexadecimal) {
    int decimal = 0;
    int power = 0;

    for (int i = hexadecimal.length() - 1; i >= 0; --i) {
        int digit;
        if (hexadecimal[i] >= '0' && hexadecimal[i] <= '9') {
            digit = hexadecimal[i] - '0';
        } else if (hexadecimal[i] >= 'a' && hexadecimal[i] <= 'f') {
            digit = hexadecimal[i] - 'a' + 10;
        } else {
            digit = hexadecimal[i] - 'A' + 10;
        }
        decimal += digit * pow(16, power);
        ++power;
    }

    return decimal;
}

int main() {
    std::string input;
    std::cout << "Enter a binary or hexadecimal number: ";
    std::cin >> input;

    int decimal;

    if (isBinary(input)) {
        if (input.length() > 16) {
            std::cout << "Error: Binary number exceeds 16 bits in length." << std::endl;
            return 0;
        }
        decimal = binaryToDecimal(input);
    } else if (isHexadecimal(input)) {
        decimal = hexadecimalToDecimal(input);
    } else {
        std::cout << "Error: Invalid input. Please enter a binary or hexadecimal number." << std::endl;
        return 0;
    }

    std::cout << "Decimal equivalent: " << decimal << std::endl;

    return 0;
}
```

