class ExistingServiceException extends Exception {}
class NonExistentServiceException extends Exception {}

class ServiceRegistry {
    private static $services = [];

    public static function registerService($serviceName, $service) {
        if (!is_object($service)) {
            throw new \InvalidArgumentException("Service must be an object");
        }

        if (array_key_exists($serviceName, self::$services)) {
            throw new ExistingServiceException("Service with name '$serviceName' already exists");
        }

        self::$services[$serviceName] = $service;
    }

    public static function getService($serviceName) {
        if (array_key_exists($serviceName, self::$services)) {
            return self::$services[$serviceName];
        } else {
            throw new NonExistentServiceException("Service with name '$serviceName' does not exist");
        }
    }
}

