struct TasksReducer {
    static func reducer(_ action: TasksAction, _ state: TasksState) -> TasksState {
        var state = state
        switch action {
        case let .addTask(title):
            let newTask = Task(id: state.tasks.count + 1, title: title, completed: false)
            state.tasks.append(newTask)
        case let .completeTask(id):
            if let index = state.tasks.firstIndex(where: { $0.id == id }) {
                state.tasks[index].completed = true
            }
        case let .selectTask(id):
            state.selectedTask = state.tasks.first { $0.id == id }
        }
        return state
    }
}
