import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class AlphanumericIDGenerator {
    private static final String UPPERCASE_LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String LOWERCASE_LETTERS = "abcdefghijklmnopqrstuvwxyz";
    private static final String NUMBERS = "0123456789";
    private static final String SPECIAL_CHARACTERS = "!@#$%^&*";

    public static void main(String[] args) {
        String alphanumericID = generateAlphanumericID();
        System.out.println(alphanumericID);
    }

    public static String generateAlphanumericID() {
        List<Character> idList = new ArrayList<>();

        // Add one uppercase letter, lowercase letter, and number at the beginning
        idList.add(getRandomCharacter(UPPERCASE_LETTERS));
        idList.add(getRandomCharacter(LOWERCASE_LETTERS));
        idList.add(getRandomCharacter(NUMBERS));

        // Add at least 2 special characters distributed throughout the ID
        idList.add(getRandomCharacter(SPECIAL_CHARACTERS));
        idList.add(getRandomCharacter(SPECIAL_CHARACTERS));

        // Add at least 15 distinct letters and 15 distinct numbers
        addDistinctCharacters(idList, UPPERCASE_LETTERS, 15);
        addDistinctCharacters(idList, LOWERCASE_LETTERS, 15);
        addDistinctCharacters(idList, NUMBERS, 15);

        // Shuffle the characters to ensure randomness
        Collections.shuffle(idList);

        // Convert the character list to a string
        StringBuilder idBuilder = new StringBuilder(idList.size());
        for (Character character : idList) {
            idBuilder.append(character);
        }

        return idBuilder.toString();
    }

    private static void addDistinctCharacters(List<Character> idList, String characterSet, int count) {
        Random random = new Random();
        while (idList.size() < count) {
            char randomChar = getRandomCharacter(characterSet);
            if (!idList.contains(randomChar)) {
                idList.add(randomChar);
            }
        }
    }

    private static char getRandomCharacter(String characterSet) {
        Random random = new Random();
        return characterSet.charAt(random.nextInt(characterSet.length()));
    }
}
