#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

#define MAX_SIZE 100

typedef struct {
    char letter;
    int count;
} LetterCount;

int compare(const void *a, const void *b) {
    const LetterCount *letterCountA = (const LetterCount *)a;
    const LetterCount *letterCountB = (const LetterCount *)b;

    if (letterCountA->count == letterCountB->count) {
        return letterCountA->letter - letterCountB->letter;
    } else {
        return letterCountB->count - letterCountA->count;
    }
}

void countLetters(const char *sentence) {
    LetterCount letters[26];
    memset(letters, 0, sizeof(letters));

    int i = 0;
    while (sentence[i] != '\0') {
        char ch = tolower(sentence[i]);
        if (isalpha(ch)) {
            letters[ch - 'a'].letter = ch;
            letters[ch - 'a'].count++;
        }
        i++;
    }

    qsort(letters, 26, sizeof(LetterCount), compare);

    for (i = 0; i < 26; i++) {
        if (letters[i].count > 0) {
            printf("%c: %d\n", letters[i].letter, letters[i].count);
        }
    }
}

int main() {
    char sentence[MAX_SIZE];

    printf("Enter a sentence: ");
    fgets(sentence, sizeof(sentence), stdin);

    countLetters(sentence);

    return 0;
}
```

This program first defines a struct `LetterCount` to store the letter and its count. It then defines a comparison function `compare` to be used by `qsort` for sorting the letters. 

In the `countLetters` function, an array of `LetterCount` is initialized to zero using `memset`. The function then iterates over each character in the sentence, converts it to lowercase using `tolower`, and checks if it is a letter using `isalpha`. If it is a letter, the count for that letter is incremented.

After counting all the letters, `qsort` is used to sort the array of `LetterCount` objects based on the count and the letter. Finally, the sorted array is printed in descending order of occurrences, with letters having the same occurrences sorted alphabetically.

