function rgbToHex(red, green, blue, includePrefix = false) {
  // Convert negative RGB values to positive
  red = Math.abs(red);
  green = Math.abs(green);
  blue = Math.abs(blue);

  // Round or truncate floating-point RGB values to integers
  red = Math.round(red);
  green = Math.round(green);
  blue = Math.round(blue);

  // Validate input RGB values
  if (red < 0 || red > 255 || green < 0 || green > 255 || blue < 0 || blue > 255) {
    throw new Error('Invalid RGB values');
  }

  // Convert RGB to HEX using bitwise operations
  let hex = ((red << 16) | (green << 8) | blue).toString(16);

  // Add leading zeros if necessary
  while (hex.length < 6) {
    hex = '0' + hex;
  }

  // Add prefix if specified
  if (includePrefix) {
    hex = '#' + hex;
  }

  return hex;
}
```

