To solve this problem, we can use a recursive approach to iterate over the json and extract all the key-value pairs.

Here is the code to parse the json and convert it into a list of key-value dictionaries:

```python
import json

def parse_json(json_data):
    result = []

    def parse_object(obj, prefix=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                if isinstance(value, (dict, list)):
                    parse_object(value, new_prefix)
                else:
                    result.append({"key": new_prefix, "value": value})
        elif isinstance(obj, list):
            for index, value in enumerate(obj):
                new_prefix = f"{prefix}[{index}]"
                if isinstance(value, (dict, list)):
                    parse_object(value, new_prefix)
                else:
                    result.append({"key": new_prefix, "value": value})

    parse_object(json_data)
    return result

# Example usage
json_data = '''
{
  "key1": "value1",
  "key2": {
    "subkey1": "subvalue1",
    "subkey2": [1, 2, 3]
  },
  "key3": [4, 5, 6]
}
'''

parsed_data = parse_json(json.loads(json_data))
for item in parsed_data:
