void swapIntParts(float *num1, float *num2) {
    int intPart1 = (int)(*num1);
    int intPart2 = (int)(*num2);

    *num1 = intPart2 + (*num1 - intPart1);
    *num2 = intPart1 + (*num2 - intPart2);
}

int main() {
    float num1 = 3.14;
    float num2 = 6.28;

    printf("Before swapping: num1 = %.2f, num2 = %.2f\n", num1, num2);

    swapIntParts(&num1, &num2);

    printf("After swapping: num1 = %.2f, num2 = %.2f\n", num1, num2);

