public class LargestTwinPrimeNumber {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<Integer> numbers = new ArrayList<>();

        System.out.println("Enter a list of numbers (enter a negative number to stop):");

        int num;
        while ((num = scanner.nextInt()) >= 0) {
            numbers.add(num);
        }

        int largestTwinPrime = findLargestTwinPrime(numbers);

        if (largestTwinPrime == -1) {
            System.out.println("No twin prime number found in the input.");
        } else {
            System.out.println("The largest twin prime number is: " + largestTwinPrime);
        }
    }

    public static int findLargestTwinPrime(List<Integer> numbers) {
        int largestTwinPrime = -1;

        for (int num : numbers) {
            if (isPrime(num) && (isPrime(num - 2) || isPrime(num + 2))) {
                largestTwinPrime = Math.max(largestTwinPrime, num);
            }
        }

        return largestTwinPrime;
    }

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}

