Here's the implementation of the `DoublyLinkedList` class:

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def addFront(self, value):
        if not isinstance(value, int) or value <= 0:
            return

        node = Node(value)
        if self.head is None:
            self.head = node
            self.tail = node
        else:
            node.next = self.head
            self.head.prev = node
            self.head = node

    def addBack(self, value):
        if not isinstance(value, int) or value <= 0:
            return

        node = Node(value)
        if self.tail is None:
            self.head = node
            self.tail = node
        else:
            node.prev = self.tail
            self.tail.next = node
            self.tail = node

    def contains(self, value):
        if not isinstance(value, int) or value <= 0:
            return False

        current = self.head
        while current:
            if current.value == value:
                return True
            current = current.next
        return False

    def removeFront(self):
        if self.head is None:
            return

        if self.head == self.tail:
            self.head = None
            self.tail = None
        else:
            self.head = self.head.next
            self.head.prev = None

    def removeBack(self):
        if self.tail is None:
            return

        if self.head == self.tail:
            self.head = None
            self.tail = None
        else:
            self.tail = self.tail.prev
            self.tail.next = None

    def remove(self, value):
        if not isinstance(value, int) or value <= 0:
            return

        current = self.head
        while current:
            if current.value == value:
                if current == self.head:
                    self.removeFront()
                elif current == self.tail:
                    self.removeBack()
                else:
                    current.prev.next = current.next
                    current.next.prev = current.prev
            current = current.next
```

This implementation uses a `Node` class to represent each node in the doubly linked list. The `DoublyLinkedList` class keeps track of the head and tail nodes of the list. The `addFront` and `addBack` methods add new nodes to the front and back of the list, respectively. The `contains` method checks if the list contains a given value. The `removeFront` and `removeBack` methods remove the nodes at the front and back of the list, respectively. The `remove` method removes all occurrences of nodes with the given value.

