        if action_type == 'normal':
            self.normal_actions.append(action)
        elif action_type == 'special':
            self.special_actions.insert(0, action)  # Insert special actions at the beginning

    def remove_action(self, action):
        if action in self.normal_actions:
            self.normal_actions.remove(action)
        elif action in self.special_actions:
            self.special_actions.remove(action)

    def execute_pending_actions(self):
