Here is a custom implementation of a Hashtable in Java with the specified requirements:

```java
import java.util.*;

public class CustomHashtable implements Iterable<Map.Entry<String, Integer>> {
    private static final int MAX_SIZE = 100;
    private LinkedHashMap<String, Integer> hashtable;

    public CustomHashtable() {
        hashtable = new LinkedHashMap<String, Integer>(MAX_SIZE, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry<String, Integer> eldest) {
                return size() > MAX_SIZE;
            }
        };
    }

    public int getValue(String key) throws NullValueException {
        if (!hashtable.containsKey(key)) {
            return -1;
        }

        Integer value = hashtable.get(key);
        if (value == null) {
            throw new NullValueException();
        }

        return value;
    }

    public void addKeyValuePair(String key, int value) throws NegativeValueException {
        if (value < 0) {
            throw new NegativeValueException();
        }

        hashtable.put(key, value);
    }

    public Iterator<Map.Entry<String, Integer>> iterator() throws EmptyHashtableException {
        if (hashtable.isEmpty()) {
            throw new EmptyHashtableException();
        }

        List<Map.Entry<String, Integer>> list = new ArrayList<>(hashtable.entrySet());
        Collections.reverse(list);
        return list.iterator();
    }

    public static class NullValueException extends Exception {
        public NullValueException() {
            super("Null value associated with the key");
        }
    }

    public static class NegativeValueException extends Exception {
        public NegativeValueException() {
            super("Negative value not allowed");
        }
    }

    public static class EmptyHashtableException extends Exception {
        public EmptyHashtableException() {
            super("Hashtable is empty");
        }
    }
}
```

