import sys
from datetime import datetime

class TaskManager:
    def __init__(self):
        self.tasks = []

    def addTask(self, task_description):
        self.tasks.append({"description": task_description, "completed": False})

    def viewTasks(self):
        for index, task in enumerate(self.tasks):
            status = "Completed" if task["completed"] else "Pending"
            print(f"{index + 1}. {task['description']} - {status}")

    def completeTask(self, task_index):
        if 0 < task_index <= len(self.tasks):
            self.tasks[task_index - 1]["completed"] = True
        else:
            print("Invalid task index.")

    def exitProgram(self):
        print("Sortie du programme : " + self.get_dateNow())
        sys.exit()

    @staticmethod
    def get_dateNow():
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

# Example usage
