        bool isValid = true;
        for (char c : roman) {
            if (romanNumerals.find(c) == romanNumerals.end()) {
                isValid = false;
                break;
            }
        }

        if (isValid) {
            break;
        }
        else {
            std::cout << "Invalid Roman numeral. Try again." << std::endl;
        }
    }
    return roman;
}

