        if len(self.lst) > 0:
            return round(sum(self.lst) / len(self.lst), 2)
        else:
            return None

    def get_max(self):
        if len(self.lst) > 0:
            return max(self.lst)
        else:
            return None

    def get_min(self):
        if len(self.lst) > 0:
            return min(self.lst)
        else:
            return None

    def get_median(self):
        if len(self.lst) > 0:
            sorted_lst = sorted(self.lst)
            mid_index = len(self.lst) // 2
            if len(self.lst) % 2 == 0:
                return (sorted_lst[mid_index-1] + sorted_lst[mid_index]) / 2
            else:
                return sorted_lst[mid_index]
        else:
            return None

    def get_mode(self):
        if len(self.lst) > 0:
            count_dict = {}
            for num in self.lst:
                if num in count_dict:
                    count_dict[num] += 1
                else:
                    count_dict[num] = 1
            max_count = max(count_dict.values())
            mode_list = [num for num, count in count_dict.items() if count == max_count]
            return mode_list[0]
        else:
            return None

    def get_product(self):
        if len(self.lst) > 0:
            product = 1
            for num in self.lst:
                product *= num
            return product
        else:
            return None

