public static boolean checkNumber(int num) {
    if (num == 0) return true; // 0 is a multiple of 10, divisible by 3, and a perfect square

    // Check if the last digit is 0
    String strNum = String.valueOf(num);
    if (strNum.charAt(strNum.length() - 1) != '0') return false;

    // Check if the sum of the digits is divisible by 3
    int sum = 0;
    for (int i = 0; i < strNum.length(); i++) {
        sum += Character.getNumericValue(strNum.charAt(i));
    }
    if (sum % 3 != 0) return false;

    // Check if the square root of the number is an integer
    int sqrt = (int) Math.sqrt(num);
    if (sqrt * sqrt != num) return false;

    return true;
}
```

