```java
import java.util.HashMap;
import java.util.Map;

public class Student {
    private String name;
    private int age;
    private Map<String, Double> grades;

    public Student(String name, int age) {
        this.name = name;
        this.age = age;
        this.grades = new HashMap<>();
    }

    public void addGrade(String subject, double grade) {
        grades.put(subject, grade);
    }

    public double calculateGPA(Map<String, Double> subjectWeightages, Map<String, Double[]> subjectGradingScales) throws InvalidGradeException {
        double totalWeightedGrade = 0;
        double totalWeightage = 0;

        for (Map.Entry<String, Double> entry : grades.entrySet()) {
            String subject = entry.getKey();
            double grade = entry.getValue();

            if (!subjectWeightages.containsKey(subject) || !subjectGradingScales.containsKey(subject)) {
                throw new InvalidGradeException("Invalid subject: " + subject);
            }

            double weightage = subjectWeightages.get(subject);
            Double[] gradingScale = subjectGradingScales.get(subject);

            if (grade < gradingScale[0] || grade > gradingScale[1]) {
                throw new InvalidGradeException("Invalid grade for subject " + subject + ": " + grade);
            }

            totalWeightedGrade += grade * weightage;
            totalWeightage += weightage;
        }

        if (totalWeightage == 0) {
            return 0;
        }

        return totalWeightedGrade / totalWeightage;
    }

    public int getRanking(Map<String, Student> allStudents) {
        int ranking = 1;
        double gpa = calculateGPA(new HashMap<>(), new HashMap<>());

        for (Student student : allStudents.values()) {
            if (student.calculateGPA(new HashMap<>(), new HashMap<>()) > gpa) {
                ranking++;
            } else if (student.calculateGPA(new HashMap<>(), new HashMap<>()) == gpa && student.age < age) {
                ranking++;
            }
        }

        return ranking;
    }

    public char getLetterGrade(String subject, Map<String, Double[]> subjectGradingScales) {
        double grade = grades.get(subject);
        Double[] gradingScale = subjectGradingScales.get(subject);

        if (grade >= gradingScale[0] && grade <= gradingScale[1]) {
            if (grade >= 90) {
                return 'A';
            } else if (grade >= 80) {
                return 'B';
            } else if (grade >= 70) {
                return 'C';
            } else if (grade >= 60) {
                return 'D';
            } else {
                return 'F';
            }
        } else {
            return '-';
        }
    }

    // Additional methods

    public int getSubjectRanking(String subject, Map<String, Student> allStudents) {
        int ranking = 1;
        double grade = grades.get(subject);

        for (Student student : allStudents.values()) {
            if (student.grades.containsKey(subject) && student.grades.get(subject) > grade) {
                ranking++;
            } else if (student.grades.containsKey(subject) && student.grades.get(subject) == grade && student.age < age) {
                ranking++;
            }
        }

        return ranking;
    }

    public int getRanking(Map<String, Double> subjectWeightages, Map<String, Double[]> subjectGradingScales, Map<String, Student> allStudents) {
        int ranking = 1;
        double gpa = calculateGPA(subjectWeightages, subjectGradingScales);

        for (Student student : allStudents.values()) {
            if (student.calculateGPA(subjectWeightages, subjectGradingScales) > gpa) {
                ranking++;
            } else if (student.calculateGPA(subjectWeightages, subjectGradingScales) == gpa && student.age < age) {
                ranking++;
            }
        }

        return ranking;
    }

    public void updateGrade(String subject, double grade) throws InvalidGradeException {
        if (!grades.containsKey(subject)) {
            throw new InvalidGradeException("Invalid subject: " + subject);
        }

        Double[] gradingScale = subjectGradingScales.get(subject);

        if (grade < gradingScale[0] || grade > gradingScale[1]) {
            throw new InvalidGradeException("Invalid grade for subject " + subject + ": " + grade);
        }

        grades.put(subject, grade);
    }

    public Map<String, String> getGradeSummary(Map<String, Double[]> subjectGradingScales) {
        Map<String, String> gradeSummary = new HashMap<>();

        for (Map.Entry<String, Double> entry : grades.entrySet()) {
            String subject = entry.getKey();
            double grade = entry.getValue();
            char letterGrade = getLetterGrade(subject, subjectGradingScales);

            gradeSummary.put(subject, "Grade: " + grade + ", Letter Grade: " + letterGrade);
        }

        return gradeSummary;
    }
}
