import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class NumberSeparationProgram {
    public static void main(String[] args) {
        List<Integer> numbers = readNumbers();
        List<Integer> evenNumbers = new ArrayList<>();
        List<Integer> oddNumbers = new ArrayList<>();
        List<Integer> primeNumbers = new ArrayList<>();
        List<Integer> evenAndPrimeNumbers = new ArrayList<>();

        separateNumbers(numbers, evenNumbers, oddNumbers, primeNumbers, evenAndPrimeNumbers);

        System.out.println("Even numbers: " + evenNumbers);
        System.out.println("Odd numbers: " + oddNumbers);
        System.out.println("Prime numbers: " + primeNumbers);
        System.out.println("Even and prime numbers: " + evenAndPrimeNumbers);
    }

    private static List<Integer> readNumbers() {
        List<Integer> numbers = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the number of integers: ");
        int count = scanner.nextInt();

        System.out.println("Enter the integers:");

        for (int i = 0; i < count; i++) {
            try {
                int number = scanner.nextInt();
                numbers.add(number);
            } catch (Exception e) {
                System.out.println("Invalid input. Only integers are accepted. Please try again.");
                scanner.nextLine(); // Clear the input buffer
                i--; // Retry input for the current index
            }
        }

        return numbers;
    }

    private static void separateNumbers(List<Integer> numbers, List<Integer> evenNumbers, List<Integer> oddNumbers,
                                        List<Integer> primeNumbers, List<Integer> evenAndPrimeNumbers) {
        separateNumbersHelper(numbers, evenNumbers, oddNumbers, primeNumbers, evenAndPrimeNumbers, 0);
    }

    private static void separateNumbersHelper(List<Integer> numbers, List<Integer> evenNumbers, List<Integer> oddNumbers,
                                              List<Integer> primeNumbers, List<Integer> evenAndPrimeNumbers, int index) {
        if (index >= numbers.size()) {
            return;
        }

        int number = numbers.get(index);

        if (number % 2 == 0 && isPrime(number)) {
            evenAndPrimeNumbers.add(number);
        } else if (number % 2 == 0) {
            evenNumbers.add(number);
        } else if (isPrime(number)) {
            primeNumbers.add(number);
        } else {
            oddNumbers.add(number);
        }

        separateNumbersHelper(numbers, evenNumbers, oddNumbers, primeNumbers, evenAndPrimeNumbers, index + 1);
    }

    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}
```

