    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_next_primes(num, count):
    if num <= 0:
        return "Input number must be a positive integer."
    primes = []
    next_num = num + 1
    while len(primes) < count:
        if is_prime(next_num):
            primes.append(next_num)
        next_num += 1
    return primes

