class Rectangle {
  constructor(length, breadth) {
    if (length <= 0 || breadth <= 0) {
      throw new Error("Length and breadth must be positive numbers greater than 0");
    }
    this.length = length;
    this.breadth = breadth;
  }

  getArea() {
    return this.length * this.breadth;
  }

  getPerimeter() {
    return 2 * (this.length + this.breadth);
  }

  isSquare() {
    return this.length === this.breadth;
  }

  resize(scaleFactor) {
    this.length *= scaleFactor;
    this.breadth *= scaleFactor;
  }

  rotate() {
    [this.length, this.breadth] = [this.breadth, this.length];
  }

  isRectangle() {
    return this instanceof Rectangle;
  }

  static compare(rectangle1, rectangle2) {
    return rectangle1.getArea() === rectangle2.getArea();
  }

  static fromArea(area) {
    const length = Math.sqrt(area);
    return new Rectangle(length, length);
  }
}

