import json
import argparse
import datetime
import logging
from multiprocessing import Pool

# Define the required keys and their data types for the schema validation
schema = {
    "name": str,
    "age": str,
    "data": {
        "city": str
    }
}

def flatten_dict(d, parent_key='', sep='.'):
    """
    Recursively flatten a dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, list):
            items.extend(flatten_list(v, new_key, sep=sep).items())
        else:
            items.append((new_key, str(v)))
    return dict(items)

def flatten_list(lst, parent_key='', sep='.'):
    """
    Recursively flatten a list.
    """
    items = []
    for i, v in enumerate(lst):
        new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        elif isinstance(v, list):
            items.extend(flatten_list(v, new_key, sep=sep).items())
        else:
            items.append((new_key, str(v)))
    return dict(items)

def marshal_json(data, output_file):
    """
    Marshal a JSON object with the specified requirements.
    """
    try:
        # Convert "age" value to string
        data["age"] = str(data["age"])

        # Add additional key-value pair to "data" dictionary
        data["data"]["city"] = "New York"

        # Flatten the JSON object
        flattened_data = flatten_dict(data)
        flattened_data = dict(sorted(flattened_data.items()))

        # Create a custom JSON encoder class
        class CustomJSONEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, datetime.datetime):
                    return obj.strftime('%Y-%m-%d %H:%M:%S')
                return super().default(obj)

        # Pretty-print the marshalled JSON object with proper indentation
        marshalled_json = json.dumps(flattened_data, indent=4, cls=CustomJSONEncoder)

        # Validate the marshalled JSON object against the schema
        try:
            json_data = json.loads(marshalled_json)
            for key, value in schema.items():
                if key not in json_data:
                    logging.error(f"Missing key: {key}")
                elif not isinstance(json_data[key], value):
                    logging.error(f"Invalid data type for key {key}. Expected {value}, got {type(json_data[key])}")
        except json.JSONDecodeError:
            logging.error("Invalid JSON format")

        # Write the marshalled JSON object to the output file using a context manager
        with open(output_file, 'w') as f:
            f.write(marshalled_json)

        # Print the marshalled JSON object
        print(marshalled_json)

    except Exception as e:
        logging.error(str(e))

if __name__ == "__main__":
    # Set up logging configuration
    logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

    # Parse command line arguments
    parser = argparse.ArgumentParser()
    parser.add_argument("-o", "--output", default="output.json", help="Output file name")
    args = parser.parse_args()

    # Input data for marshalling
    data = {
        "name": "John Doe",
        "age": 30,
        "data": {
            "address": {
                "street": "123 Main St",
                "city": "Los Angeles"
            }
        }
    }

    # Use multiprocessing to improve performance
    pool = Pool(processes=1)
    pool.apply_async(marshal_json, args=(data, args.output))
    pool.close()
    pool.join()

