#import <Foundation/Foundation.h>

BOOL areAnagrams(NSString *string1, NSString *string2) {
    // Remove whitespace, punctuation, and special characters from both strings
    NSCharacterSet *characterSet = [[NSCharacterSet alphanumericCharacterSet] invertedSet];
    NSString *cleanString1 = [[string1 componentsSeparatedByCharactersInSet:characterSet] componentsJoinedByString:@""];
    NSString *cleanString2 = [[string2 componentsSeparatedByCharactersInSet:characterSet] componentsJoinedByString:@""];

    // Convert both strings to lowercase
    NSString *lowercaseString1 = [cleanString1 lowercaseString];
    NSString *lowercaseString2 = [cleanString2 lowercaseString];

    // Check if the lengths of the two strings are equal
    if (lowercaseString1.length != lowercaseString2.length) {
        NSLog(@"The strings are not anagrams.");
        return NO;
    }

    // Create two arrays to store the frequency of each character
    NSMutableArray *frequencyArray1 = [NSMutableArray arrayWithCapacity:26];
    NSMutableArray *frequencyArray2 = [NSMutableArray arrayWithCapacity:26];

    // Initialize both arrays with zeros
    for (int i = 0; i < 26; i++) {
        [frequencyArray1 addObject:@(0)];
        [frequencyArray2 addObject:@(0)];
    }

    // Iterate over each character in the first string and increment the corresponding index in the first array
    for (int i = 0; i < lowercaseString1.length; i++) {
        unichar character = [lowercaseString1 characterAtIndex:i];
        int index = character - 'a';
        int frequency = [frequencyArray1[index] intValue];
        frequencyArray1[index] = @(frequency + 1);
    }

    // Iterate over each character in the second string and increment the corresponding index in the second array
    for (int i = 0; i < lowercaseString2.length; i++) {
        unichar character = [lowercaseString2 characterAtIndex:i];
        int index = character - 'a';
        int frequency = [frequencyArray2[index] intValue];
        frequencyArray2[index] = @(frequency + 1);
    }

    // Compare the two arrays element by element
    for (int i = 0; i < 26; i++) {
        if (![frequencyArray1[i] isEqualToNumber:frequencyArray2[i]]) {
            NSLog(@"The strings are not anagrams.");
            return NO;
        }
    }

    NSLog(@"The strings are anagrams.");
    return YES;
}

