def url_monitor(url: str, response_threshold: int, timeout: int) -> bool:
    consecutive_successes = 0
    start_time = time.time()

    while time.time() - start_time < timeout:
        try:
            response = requests.get(url)
            if response.status_code // 100 == 2:  # Check if the status code is in the 2xx range
                consecutive_successes += 1
                if consecutive_successes >= response_threshold:
                    return True
            else:
                consecutive_successes = 0  # Reset consecutive successes if the response is not successful
        except requests.RequestException:
            consecutive_successes = 0  # Reset consecutive successes on request exception
        time.sleep(1)  # Wait for 1 second before sending the next request

    return False  # Return False if the response threshold is not met within the timeout period
