#include <stdio.h>

void reverseString(char* str) {
    if (*str == '\0') {
        return;
    }

    char* end = str;
    while (*(end + 1) != '\0') {
        end++;
    }

    char temp;
    while (str < end) {
        temp = *str;
        *str = *end;
        *end = temp;
        str++;
        end--;
    }
}

int main() {
    char str[] = "Hello, World!";
    printf("Original string: %s\n", str);
    reverseString(str);
    printf("Reversed string: %s\n", str);

