class PrimeNumberIterator:
    def __init__(self, start, end):
        self.start = start
        self.end = end

    def is_prime(self, num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def __iter__(self):
        self.num = self.start
        return self

    def __next__(self):
        while self.num <= self.end:
            if self.is_prime(self.num):
                prime_num = self.num
                self.num += 1
                return prime_num
            self.num += 1
        raise StopIteration


