        self.base_kit = base_kit
        self.args = []

    def add_argument(self, arg):
        if arg not in self.args:
            self.args.append(arg)

    def remove_argument(self, arg):
        if arg in self.args:
            self.args.remove(arg)
        else:
            print(f'Error: Argument "{arg}" does not exist.')

    def update_argument(self, old_arg, new_arg):
        if old_arg in self.args:
            index = self.args.index(old_arg)
            self.args[index] = new_arg
        else:
            print(f'Error: Argument "{old_arg}" does not exist.')

    def parse_arguments(self):
        new_args = []
        for arg in self.args:
            if arg not in new_args:
                new_args.append(arg)
            else:
                print('Error: Duplicate argument detected.')
        self.args = new_args
        self.request = self.base_kit.parser.parse_args(self.args)
