Here is a JavaScript code that compares the values of two strings without using any built-in string comparison functions or methods:

```javascript
function compareStrings(string1, string2) {
  var len1 = 0, len2 = 0;

  // Find lengths of both strings
  while (string1[len1] !== undefined) {
    len1++;
  }
  while (string2[len2] !== undefined) {
    len2++;
  }

  // Compare lengths
  if (len1 < len2) {
    console.log("String 2 is longer");
  } else if (len1 > len2) {
    console.log("String 1 is longer");
  } else {
    console.log("Both strings have the same length");
  }

  // Compare values of each character
  var i = 0, j = 0;
  while (string1[i] !== undefined && string2[j] !== undefined) {
    if (string1[i] < string2[j]) {
      console.log("String 1 is smaller");
      return;
    } else if (string1[i] > string2[j]) {
      console.log("String 2 is smaller");
      return;
    }
    i++;
    j++;
  }

  // If all characters are same, but lengths are different
  if (string1[i] === undefined && string2[j] !== undefined) {
    console.log("String 1 is smaller");
  } else if (string1[i] !== undefined && string2[j] === undefined) {
    console.log("String 2 is smaller");
  } else {
    console.log("Both strings are equal");
  }
}

// Example usage
compareStrings("apple", "banana");
compareStrings("cat", "dog");
compareStrings("hello", "hello");
```

This code first finds the lengths of both strings using a `while` loop. Then it compares the lengths and displays a message accordingly. After that, it compares the values of each character in the strings and displays a message indicating which string is smaller or if they are equal.

