def all_keys(d: Union[dict, list]) -> list:
    keys = []
    if isinstance(d, dict):
        for key, value in d.items():
            keys.append(key)
            keys.extend(all_keys(value))
    elif isinstance(d, list):
        for item in d:
            keys.extend(all_keys(item))
    return keys
