public class GameController {
    private boolean playerControl;
    private String message;

    public GameController() {
        playerControl = true;
        message = "Automatic control enabled.";
    }

    public void setState(String state) {
        if (state.equals("AUTOMATIC")) {
            playerControl = true;
            message = "Automatic control enabled.";
        } else if (state.equals("MANUAL")) {
            playerControl = false;
            message = "I'm on my own now (WASD to control + Press F to change).";
        }
    }

    public void handleKeyPress(char key) {
        if (playerControl && key == 'F') {
            if (message.equals("Automatic control enabled.")) {
                playerControl = false;
                message = "I'm on my own now (WASD to control + Press F to change).";
            } else {
                playerControl = true;
                message = "Automatic control enabled.";
            }
        }
    }
}
