import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def find_highest_prime(numbers):
    primes = set()
    highest_prime = None
    for num in numbers:
        if num > 0 and is_prime(num):
            if num in primes:
                raise ValueError("Duplicate prime numbers found")
            primes.add(num)
            if highest_prime is None or num > highest_prime:
                highest_prime = num
    if highest_prime is None:
        raise ValueError("No prime numbers found")
    return highest_prime
```

