def decimal_to_roman(decimal_num, uppercase=True):
    if not isinstance(decimal_num, (int, float)):
        raise ValueError("Input number must be a positive integer or float.")
    elif decimal_num <= 0 or decimal_num >= 10000:
        raise ValueError("Input number must be a positive integer less than 10000.")

    num = int(round(decimal_num))

    roman_numerals = {
        1000: 'M',
        900: 'CM',
        500: 'D',
        400: 'CD',
        100: 'C',
        90: 'XC',
        50: 'L',
        40: 'XL',
        10: 'X',
        9: 'IX',
        5: 'V',
        4: 'IV',
        1: 'I'
    }

    if num == 0:
        return "Nulla" if uppercase else "nulla"

    roman_numeral = ""
    for value, symbol in roman_numerals.items():
        while num >= value:
            roman_numeral += symbol
            num -= value

    return roman_numeral.upper() if uppercase else roman_numeral.lower()


def binary_to_decimal(binary_num):
    if not isinstance(binary_num, str):
        raise ValueError("Input number must be a binary string.")

    decimal_num = int(binary_num, 2)
    return decimal_num


def convert_to_roman_numeral(num, uppercase=True):
    if isinstance(num, str) and num.isdigit():
        decimal_num = int(num)
    elif isinstance(num, str) and num.isalpha():
        try:
            decimal_num = binary_to_decimal(num)
        except ValueError:
            raise ValueError("Input number must be a positive integer or binary string.")
    elif isinstance(num, (int, float)):
        decimal_num = num
    else:
        raise ValueError("Input number must be a positive integer or float.")

    return decimal_to_roman(decimal_num, uppercase)
